  Widget history(){final items=[['temperature','Temperature','°C'],['humidity','Humidity','%'],['pressure','Pressure','hPa'],['uv','UV',''],['visible_light','Visible light',''],['battery_v','Battery','V']];return ListView(padding:const EdgeInsets.all(16),children:[Text(tx('History & graphs','Sejarah & graf'),style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:10),SegmentedButton<String>(segments:const[ButtonSegment(value:'1h',label:Text('1h')),ButtonSegment(value:'6h',label:Text('6h')),ButtonSegment(value:'24h',label:Text('24h')),ButtonSegment(value:'7d',label:Text('7d')),ButtonSegment(value:'30d',label:Text('30d'))],selected:{range},onSelectionChanged:(s)=>setState(()=>range=s.first)),...items.map((x)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${x[1]} ${x[2]}',style:const TextStyle(fontWeight:FontWeight.bold)),chart(x[0],160),Wrap(spacing:5,children:[Chip(label:Text('Min ${f(mn(x[0]))}')),Chip(label:Text('Avg ${f(av(x[0]))}')),Chip(label:Text('Max ${f(mx(x[0]))}'))])]))))]));}
