class Compass extends CustomPainter {final double d;Compass(this.d);@override void paint(Canvas c,Size s){final m=Offset(s.width/2,s.height/2),r=s.shortestSide/2-10,p=Paint()..style=PaintingStyle.stroke..strokeWidth=2;c.drawCircle(m,r,p);const l=['N','E','S','W'];for(int i=0;i<4;i++){final a=i*math.pi/2,pos=m+Offset(math.sin(a)*(r-20),-math.cos(a)*(r-20));final q=TextPainter(text:TextSpan(text:l[i],style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16)),textDirection:TextDirection.ltr)..layout();q.paint(c,pos-Offset(q.width/2,q.height/2));}if(!d.isNaN){final a=d*math.pi/180;c.drawLine(m,m+Offset(math.sin(a)*(r-35),-math.cos(a)*(r-35)),Paint()..strokeWidth=5..strokeCap=StrokeCap.round);}}@override bool shouldRepaint(covariant Compass o)=>o.d!=d;}
